/**
 * Material Icon Theme's matching (YAZ-3440 D4), ported for the sidebar tree: which of its icons a file or a folder
 * row shows. Pure, and O(1) per row: the release's tables (`materialIconData.ts`, generated by
 * `tools/materialIcons.mjs`) become Maps once, at load, and a row asks one Map per dot in its name.
 *
 * Files, as VS Code reads Material's manifest: an exact file name wins (`README.md`, `Makefile`, `.gitignore`,
 * `package.json`), then the longest extension (`test.ts` before `ts`; `.env` has the extension `env`), then the
 * default file. Names and extensions match in any case. Material's language-id table is not ported: the app has
 * no language ids, and the manifest's extension table covers the kinds it lists.
 * Folders: by name in any case, also with Material's prefixes (`.github`, `_lib`, `-docs`, `__tests__`), else the
 * default folder; an open folder shows its `-open` icon. A vault row shows none (Tree.tsx).
 *
 * The icons are files under `/material-icons/` (client/public), so a row loads only the icon it shows; in the
 * light theme an icon with a `_light` twin shows that one (Material's `light` table does the same).
 */
import { FILE_EXTENSIONS, FILE_NAMES, FOLDER_NAMES, MATERIAL_CLONES, MATERIAL_IDS } from './materialIconData'

const tableOf = (grouped: Record<string, string>): Map<string, string> => {
  const map = new Map<string, string>()
  for (const [icon, keys] of Object.entries(grouped)) for (const key of keys.split(' ')) map.set(key, icon)
  return map
}

const FILE_NAME = tableOf(FILE_NAMES)
const FILE_EXTENSION = tableOf(FILE_EXTENSIONS)
const FOLDER_NAME = tableOf(FOLDER_NAMES)
const IDS = new Set(MATERIAL_IDS.split(' '))
const CLONES = new Set(MATERIAL_CLONES.split(' '))

export const DEFAULT_FILE_ICON = 'file'
export const DEFAULT_FOLDER_ICON = 'folder'

/** True for an id Material ships: a pick or a rule naming any other reads as no pick (YAZ-3440 C). */
export const isMaterialIcon = (id: string): boolean => IDS.has(id)

/** The icon of a file named `name` (its base name, not a path). */
export function materialFileIcon(name: string): string {
  const lower = name.toLowerCase()
  const exact = FILE_NAME.get(lower)
  if (exact !== undefined) return exact
  // Each suffix after a dot, longest first: `a.test.ts` asks `test.ts`, then `ts`.
  for (let dot = lower.indexOf('.'); dot !== -1; dot = lower.indexOf('.', dot + 1)) {
    const icon = FILE_EXTENSION.get(lower.slice(dot + 1))
    if (icon !== undefined) return icon
  }
  return DEFAULT_FILE_ICON
}

/** Material's folder-name variants (`extendFolderNames`): `name`, `.name`, `_name`, `-name`, `__name__`. */
const PLAIN = /^(?:__(.+)__|[._-](.+))$/

/** The icon of a CLOSED folder named `name`; `openIcon` gives its open one. */
export function materialFolderIcon(name: string): string {
  const lower = name.toLowerCase()
  const exact = FOLDER_NAME.get(lower)
  if (exact !== undefined) return exact
  const m = PLAIN.exec(lower)
  const base = m?.[1] ?? m?.[2]
  return (base === undefined ? undefined : FOLDER_NAME.get(base)) ?? DEFAULT_FOLDER_ICON
}

/** A folder icon's open twin (`folder-src` → `folder-src-open`), or the icon itself when Material has none. */
export const openIcon = (id: string): string => (IDS.has(`${id}-open`) ? `${id}-open` : id)

/** Where an icon's file is served: an absolute path, so it resolves the same from inline style and from app.css. */
export const iconUrl = (id: string): string => `/material-icons/${id}${CLONES.has(id) ? '.clone' : ''}.svg`

/** The `_light` twin of an icon, for the light theme, or null when it has none. */
export const lightIcon = (id: string): string | null => (IDS.has(`${id}_light`) ? `${id}_light` : null)

/**
 * The inline custom properties that draw `id` on a row (app.css reads them on `.tree__label::before`): its URL,
 * and its light twin's when it has one. A new object per call: Tree builds it during render, beside `paddingLeft`.
 */
export function iconVars(id: string): Record<string, string> {
  const light = lightIcon(id)
  return light === null ? { '--icon': `url(${iconUrl(id)})` } : { '--icon': `url(${iconUrl(id)})`, '--icon-light': `url(${iconUrl(light)})` }
}

/** The ids the icon picker lists: every icon but the open and the light twins, which follow their icon. */
export const pickableIcons = (): string[] => [...IDS].filter((id) => !(id.endsWith('-open') && IDS.has(id.slice(0, -5))) && !(id.endsWith('_light') && IDS.has(id.slice(0, -6))))
